items.reference_kql:
let FailedWin =
    SecurityEvent
    | where EventID == 4625
    | summarize WindowsFailures = count() by IpAddress;
let Signins =
    SigninLogs
    | summarize SigninAttempts = count() by IpAddress = IPAddress;
FailedWin
| join kind=inner (Signins) on IpAddress
| project IpAddress, WindowsFailures, SigninAttempts
| sort by WindowsFailures desc, IpAddress asc

let WinHosts =
    SecurityEvent
    | where EventID == 4625
    | summarize FailedLogons = count() by Host = tolower(Computer);
let DeviceHosts =
    DeviceProcessEvents
    | summarize ProcessEvents = count() by Host = tolower(tostring(split(DeviceName, ".")[0]));
WinHosts
| join kind=inner (DeviceHosts) on Host
| project Host, FailedLogons, ProcessEvents
| sort by FailedLogons desc, Host asc
